namespace BlazorNotifications.Services;

public class Notification
{
    public int Id { get; set; }
    public string Message { get; set; } = "";
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data.
        _notifications.AddRange(new[]
        {
            new Notification { Id = _nextId++, Message = "Welcome to the app!", Timestamp = DateTime.UtcNow.AddMinutes(-10) },
            new Notification { Id = _nextId++, Message = "Your profile was updated.", Timestamp = DateTime.UtcNow.AddMinutes(-5) },
            new Notification { Id = _nextId++, Message = "New feature: dark mode is available.", Timestamp = DateTime.UtcNow.AddMinutes(-1) },
        });
    }

    /// <summary>Returns all notifications.</summary>
    public Task<List<Notification>> GetAllAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_notifications.ToList());
        }
    }

    /// <summary>Returns only notifications newer than the given id.</summary>
    public Task<List<Notification>> GetSinceAsync(int lastSeenId)
    {
        lock (_lock)
        {
            return Task.FromResult(
                _notifications.Where(n => n.Id > lastSeenId).ToList());
        }
    }

    /// <summary>Simulates a new notification arriving (called by a background generator).</summary>
    public void AddRandom()
    {
        string[] templates =
        [
            "Server health check passed.",
            "Deployment completed successfully.",
            "New comment on your post.",
            "Disk usage alert: 80% full.",
            "Scheduled backup finished.",
            "New user signed up.",
            "Payment received.",
        ];

        lock (_lock)
        {
            var msg = templates[Random.Shared.Next(templates.Length)];
            _notifications.Add(new Notification
            {
                Id = _nextId++,
                Message = msg,
                Timestamp = DateTime.UtcNow,
            });
        }
    }
}

namespace BlazorNotifications.Services;

/// <summary>
/// Background service that periodically creates fake notifications
/// so the polling page has something new to pick up.
/// </summary>
public class NotificationGenerator : BackgroundService
{
    private readonly NotificationService _notificationService;

    public NotificationGenerator(NotificationService notificationService)
        => _notificationService = notificationService;

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(7), stoppingToken);
            _notificationService.AddRandom();
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@implements IDisposable
@inject BlazorNotifications.Services.NotificationService NotificationSvc

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill">@notifications.Count</span>
</h1>

@if (notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in notifications.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <div>@n.Message</div>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<BlazorNotifications.Services.Notification> notifications = new();
    private CancellationTokenSource? _cts;

    // Persisted across prerender → interactive so we don't re-fetch.
    [PersistentState]
    public BlazorNotifications.Services.Notification[]? Saved { get; set; }

    protected override async Task OnInitializedAsync()
    {
        if (Saved is not null)
        {
            // Interactive render: restore from persisted prerender state.
            notifications = Saved.ToList();
        }
        else
        {
            // Prerender: load from service and let the framework persist.
            notifications = await NotificationSvc.GetAllAsync();
            Saved = notifications.ToArray();
        }
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // Only runs after the interactive runtime attaches — never during prerender.
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct);

            var lastId = notifications.Count > 0
                ? notifications.Max(n => n.Id)
                : 0;

            var newer = await NotificationSvc.GetSinceAsync(lastId);
            if (newer.Count > 0)
            {
                notifications.AddRange(newer);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

