namespace BlazorNotifications.Services;

public class Notification
{
    public int Id { get; set; }
    public string Message { get; set; } = "";
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        _notifications.AddRange(new[]
        {
            new Notification { Id = _nextId++, Message = "Welcome to the app!", Timestamp = DateTime.UtcNow.AddMinutes(-10) },
            new Notification { Id = _nextId++, Message = "Your profile was updated.", Timestamp = DateTime.UtcNow.AddMinutes(-5) },
            new Notification { Id = _nextId++, Message = "New feature: dark mode is available.", Timestamp = DateTime.UtcNow.AddMinutes(-1) },
        });
    }

    public Task<List<Notification>> GetAllAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_notifications.ToList());
        }
    }

    public Task<List<Notification>> GetSinceAsync(int lastSeenId)
    {
        lock (_lock)
        {
            return Task.FromResult(
                _notifications.Where(n => n.Id > lastSeenId).ToList());
        }
    }

    public void AddRandom()
    {
        string[] templates =
        [
            "Server health check passed.",
            "Deployment completed successfully.",
            "New comment on your post.",
            "Disk usage alert: 80% full.",
            "Scheduled backup finished.",
            "New user signed up.",
            "Payment received.",
        ];

        lock (_lock)
        {
            var msg = templates[Random.Shared.Next(templates.Length)];
            _notifications.Add(new Notification
            {
                Id = _nextId++,
                Message = msg,
                Timestamp = DateTime.UtcNow,
            });
        }
    }
}

namespace BlazorNotifications.Services;

/// <summary>
/// Background service that periodically creates fake notifications
/// so the polling page has something new to pick up.
/// </summary>
public class NotificationGenerator : BackgroundService
{
    private readonly NotificationService _notificationService;

    public NotificationGenerator(NotificationService notificationService)
        => _notificationService = notificationService;

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(7), stoppingToken);
            _notificationService.AddRandom();
        }
    }
}

